<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {request} from '../api.js';import {authenticated} from '../session.js';
import LoginForm from '../components/LoginForm.vue';import ReservaForm from '../components/ReservaForm.vue';import ReservaList from '../components/ReservaList.vue';
const props=defineProps({online:Boolean});const formVersion=ref(0);const reservas=ref([]),busy=ref(false),loading=ref(false),error=ref(''),success=ref(''),editing=ref(null),search=ref(''),live=ref('');
let controller,sequence=0,stream,disposed=false;
const filtered=computed(()=>reservas.value.filter(r=>r.cliente.toLowerCase().includes(search.value.toLowerCase())||r.fecha.includes(search.value)));
const guests=computed(()=>reservas.value.reduce((sum,r)=>sum+r.personas,0));
function stopStream(){stream?.close();stream=null;live.value='';}
function reset(){loading.value=false;sequence++;controller?.abort();stopStream();authenticated.value=false;reservas.value=[];editing.value=null;}
function failure(e){if(e.name==='AbortError')return;if(e.status===401)reset();error.value=e.message;}
async function load(){controller?.abort();controller=new AbortController();const current=++sequence;loading.value=true;try{const rows=await request('/reservas',{signal:controller.signal});if(!disposed&&current===sequence){reservas.value=rows;authenticated.value=true;error.value='';}}catch(e){if(!disposed&&current===sequence)failure(e);}finally{if(current===sequence)loading.value=false;}}
function listen(){stopStream();if(!props.online||!authenticated.value)return;stream=new EventSource('/api/eventos');stream.onopen=()=>{live.value='Actualización en vivo';load();};stream.addEventListener('reserva',()=>load());stream.onerror=()=>{live.value='Reconectando…';if(props.online)load();};}
async function login(token){busy.value=true;error.value='';try{await request('/sesion',{method:'POST',body:{token}});authenticated.value=true;await load();listen();}catch(e){failure(e);}finally{busy.value=false;}}
async function save(body){busy.value=true;error.value='';success.value='';try{const id=editing.value?.id;await request(id?`/reservas/${id}`:'/reservas',{method:id?'PUT':'POST',body});editing.value=null;formVersion.value++;success.value=id?'Reserva actualizada correctamente.':'Reserva creada correctamente.';await load();}catch(e){failure(e);}finally{busy.value=false;}}
async function remove(id){busy.value=true;error.value='';success.value='';try{await request(`/reservas/${id}`,{method:'DELETE'});if(editing.value?.id===id)editing.value=null;success.value='Reserva eliminada.';await load();}catch(e){failure(e);}finally{busy.value=false;}}
async function logout(){busy.value=true;error.value='';try{await request('/sesion',{method:'DELETE'});reset();success.value='';}catch(e){failure(e);}finally{busy.value=false;}}
function edit(reserva){editing.value={...reserva};success.value='';document.querySelector('#cliente')?.focus();}
watch(()=>props.online,online=>{if(!online){controller?.abort();sequence++;loading.value=false;stopStream();reservas.value=[];editing.value=null;}else{load().then(()=>{if(authenticated.value)listen();});}});
onMounted(async()=>{if(props.online){await load();if(authenticated.value)listen();}});
onUnmounted(()=>{disposed=true;controller?.abort();stopStream();});
</script>
<template><p v-if="loading&&!authenticated" role="status">Comprobando sesión…</p><LoginForm v-else-if="!authenticated" :busy="busy" :error="error" :online="online" @login="login"/><template v-else><section class="page-heading"><div><span class="eyebrow">TU AGENDA, EN UN SOLO LUGAR</span><h1>Próximas celebraciones</h1><p>Los pequeños detalles hacen grandes eventos.</p></div><button class="light" :disabled="busy||!online" @click="logout">Cerrar sesión</button></section><div class="stats"><div><small>RESERVAS REGISTRADAS</small><strong>{{reservas.length}}</strong></div><div><small>INVITADOS EN TOTAL</small><strong>{{guests}}</strong></div><div><small>CONEXIÓN</small><strong class="connection">{{online?live||'Conectado':'Sin conexión'}}</strong></div></div><p v-if="error" class="error notice" role="alert">{{error}}</p><p v-if="success" class="success notice" role="status">{{success}}</p><div class="workspace"><ReservaForm :key="formVersion" :reserva="editing" :busy="busy" :online="online" @save="save" @cancel="editing=null"/><section class="card list-card" :aria-busy="loading"><div class="list-title"><div><span class="eyebrow">AGENDA DE EVENTOS</span><h2>Tus reservas</h2></div><button class="light" :disabled="loading||busy||!online" @click="load">Actualizar</button></div><label for="buscar">Buscar por cliente o fecha</label><input id="buscar" v-model="search" type="search" placeholder="Nombre o AAAA-MM-DD"><p v-if="loading" role="status">Actualizando reservas…</p><ReservaList :reservas="filtered" :busy="busy" :online="online" @edit="edit" @delete="remove"/></section></div></template></template>
